import{_ as n,a0 as l,w as i,s as u,ao as p,I as o,x as e,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"為什麼開源對於數據分析很重要？ | LCTT x X-CMD","titleTemplate":false,"description":"為什麼開源對於數據分析很重要？ | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼開源對於數據分析很重要？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼開源對於數據分析很重要？ | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20220909 Open source matters in data analytics- Here-s why","title":"為什麼開源對於數據分析很重要？","tag":"202305","desc":""},"relativePath":"202305/20220909 Open source matters in data analytics- Here-s why.md","filePath":"[post].md"}'),d={name:"202305/20220909 Open source matters in data analytics- Here-s why.md"};function m(f,t,T,b,C,x){const a=l("Link");return i(),u("div",null,[t[18]||(t[18]=p('<h1 id="為什麼開源對於數據分析很重要" tabindex="-1">為什麼開源對於數據分析很重要？ <a class="header-anchor" href="#為什麼開源對於數據分析很重要" aria-label="Permalink to “為什麼開源對於數據分析很重要？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202305/06/093906f63kjevj5t6fe06m.png" alt=""></p><blockquote><p>開源對於數據分析非常重要，它能為用户、社區成員和公司帶來長遠利益。</p></blockquote><p>我曾經寫過介紹 Cube 社區的文章，至今已過去了一年多。隨着和社區會員以及其他供應商在一起工作，我更堅信開源對於數據分析工作是很有好處的。我也認為，需要不斷思考開源為什麼重要，以及開源是如何為人們帶來長遠利益的。</p><h3 id="開源對於用户和客户的好處" tabindex="-1">開源對於用户和客户的好處 <a class="header-anchor" href="#開源對於用户和客户的好處" aria-label="Permalink to “開源對於用户和客户的好處”">​</a></h3><p>我從 Cube 社區聽説的第一件事就是：他們經常可以從與其他社區成員的交流中得到技術支持，這種支持往往好於使用需要付費的專有軟件獲得的支持。在很多開源社區中，我發現，社區成員很樂意幫助別人（特別是幫助新手），並且把這種幫助看作回報開源社區的方式。</p><p>在開源社區，你不需要獲得許可就可以加入。一個好的開源社區不但服務於開發者，而且令人們感覺到有一種信任的文化，認為與他人在聊天室、論壇和問題跟蹤工具進行開放式討論是一件愉快的事。這對於諸如數據工程師或數據分析師之類的非開發者來説也很重要。</p>',7)),o("p",null,[t[1]||(t[1]=e("當然，藉助開源軟件，還可以直接查看代碼、修復錯誤或為項目添加新功能。以 Cube 社區為例，對於 GraphQL 的支持就是我們去年的亮點，我們的社區成員為項目 ",-1)),r(a,{href:"https://github.com/cube-js/cube.js/pull/3555"},{default:s(()=>[...t[0]||(t[0]=[e("貢獻了這些功能",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[19]||(t[19]=p('<p>對一個活躍的社區來説，也是很有好處的。即使當供應商不能及時地發佈修復版本，你仍然可以自行修改，並可以在等待官方修復版的這段時間內使用修改後的版本。社區成員和用户也不願意被供應商的奇思妙想所束縛，而且使用開源軟件時也不存在升級的壓力。</p><p>開源社區在 GitLab、GitHub、Codeberg、YouTube 等各種地方留下了很多“麪包屑”，這令衡量活躍程度和社區參與度更容易，也可以衡量社區參與和文化的水平。所以，即使在試用軟件前，你也可以在做決定之前瞭解到它的社區（以及公司）的一些情況。</p><h3 id="開源對公司的好處" tabindex="-1">開源對公司的好處 <a class="header-anchor" href="#開源對公司的好處" aria-label="Permalink to “開源對公司的好處”">​</a></h3><p>沒有其他辦法比開源更能降低使用軟件的障礙了。在早期，開源可以提高技術受眾的認知度。早期的使用者往往後來會成為你的最忠實的粉絲。</p><p>早期的使用者也是加速產品發展的催化劑。他們對於產品的反饋和功能需求（例如對問題的追蹤）能實現對真實用例的洞察。另外，很多開源愛好者可以合作開發（比如通過代碼倉庫）新功能和進行 BUG 修復。不用説，這對於創業早期的公司來説是很重要的，因為當時缺少開發和產品相關的資源。</p><p>你對社區的關注會令它發展壯大，並且呈現多樣化趨勢。多樣化不僅體現在人數和地域方面。你需要來自新興行業的用户或從事各種職業的用户。以 Cube 社區為例，在一年前我常常會跟一些開發者交流，但一年後與我交流得更多的是那些數據使用者和用户。</p><p>在良好的開源社區裏，合作文化降低了准入門檻，不僅對於開發者，對於其他提問者、分享觀點者或願意作出非技術性貢獻的人們來説都是如此。隨着公司和社區的發展，你可以更好地接觸到不同的觀點。</p><p>對包括社區成員在內的廣大人羣來説，開源使合作變得更容易。例如，你需要跟其他貢獻者在同一個資料庫驅動或集成上進行合作，如果可以通過開源倉庫進行合作，就很方便了。</p><h3 id="關於社區" tabindex="-1">關於社區 <a class="header-anchor" href="#關於社區" aria-label="Permalink to “關於社區”">​</a></h3><p>以上這些好處都降低了使用軟件和協作開發的門檻。開源模型不僅對單個軟件或公司有幫助，它還能令整個生態和行業加速發展。我希望在數據分析領域看到更多開源的公司和社區，同時希望人們持續關注開源產品。</p><p><em>（題圖：MJ/50a877f5-e0e1-4f66-91bf-f1f60b4a9023）</em></p><hr>',12)),o("p",null,[t[4]||(t[4]=e("via: ",-1)),r(a,{href:"https://opensource.com/article/22/9/open-source-data-analytics"},{default:s(()=>[...t[3]||(t[3]=[e("https://opensource.com/article/22/9/open-source-data-analytics",-1)])]),_:1})]),o("p",null,[t[9]||(t[9]=e("作者：",-1)),r(a,{href:"https://opensource.com/users/rpaik"},{default:s(()=>[...t[5]||(t[5]=[e("Ray Paik",-1)])]),_:1}),t[10]||(t[10]=e(" 選題：",-1)),r(a,{href:"https://github.com/lkxed"},{default:s(()=>[...t[6]||(t[6]=[e("lkxed",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),r(a,{href:"https://github.com/cool-summer-021"},{default:s(()=>[...t[7]||(t[7]=[e("cool-summer-021",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:s(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=e("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創編譯，",-1)),r(a,{href:"https://linux.cn/"},{default:s(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const g=n(d,[["render",m]]);export{_ as __pageData,g as default};
